'use strict';
const objectPartFields={laptop:{lidOpen:['Lid opening',0,1,.01,1],screenProgress:['Screen chart',0,1,.01,1]},phone:{messageX:['Message · X',-80,80,1,0],messageY:['Message · Y',-80,80,1,0],messageScale:['Message · size',.05,2,.01,1]},chart:Object.fromEntries([1,2,3,4].map(n=>['bar'+n,['Bar '+n,0,1,.01,1]])),clock:{hourAngle:['Hour hand',-720,720,1,0],minuteAngle:['Minute hand',-720,720,1,0],secondAngle:['Second hand',-720,720,1,0]},gear:{gearAngle:['Gear rotation',-720,720,1,0]},books:{bookX:['Top book · X',-100,100,1,0],bookY:['Top book · Y',-100,100,1,0],bookAngle:['Top book · angle',-90,90,1,0]},coins:Object.fromEntries([1,2,3].map(n=>['stack'+n+'Y',['Stack '+n+' · Y',-120,50,1,0]])),coffee:{steamOpacity:['Steam visibility',0,1,.01,1]},plant:{leafAngle:['Leaf angle',-45,45,1,0]},envelope:{letterY:['Letter position',-80,80,1,0]}};
function partDefinitions(o){return{artworkAngle:['Whole artwork · angle',-720,720,1,0],artworkScale:['Whole artwork · size',.1,3,.01,1],...(objectPartFields[o.explainerAsset?.id]||{})}}
function partDefault(o,field,t){const a=o.explainerAsset,phase=a.details?Math.max(0,t-clipStart(o))*(a.speed||1):0;if(['screenProgress','bar1','bar2','bar3','bar4'].includes(field))return a.details?.65+.35*Math.sin(phase*2):1;if(['messageY','bookY'].includes(field))return Math.sin(phase*Math.PI*2)*3;if(['hourAngle','minuteAngle'].includes(field))return(phase*.3*180/Math.PI)%360;if(field==='secondAngle')return(phase*1.4*180/Math.PI)%360;if(field==='gearAngle')return(phase*.45*180/Math.PI)%360;if(field==='leafAngle')return Math.sin(phase*Math.PI*2)*.04*180/Math.PI;if(field==='letterY')return-Math.sin(phase*Math.PI*2)*10;return partDefinitions(o)[field]?.[4]??0}
function objectPartValue(o,field,t){const keys=(o.objectAnimation?.[field]||[]).slice().sort((a,b)=>a.t-b.t);if(!keys.length||t<keys[0].t)return partDefault(o,field,t);if(t>=keys.at(-1).t)return keys.at(-1).value;const i=keys.findIndex(k=>k.t>t),a=keys[i-1],b=keys[i],f=easingAt({ease:a.ease,curve:a.curve},(t-a.t)/(b.t-a.t));const def=partDefinitions(o)[field];return clamp(a.value+(b.value-a.value)*f,def[1],def[2])}
function objectPartPose(o,t){return Object.fromEntries(Object.entries(o.objectAnimation||{}).filter(([_,keys])=>keys.length).map(([field])=>[field,objectPartValue(o,field,t)]))}
function keyObjectPart(o,field,value,t=time,ease='smooth'){const def=partDefinitions(o)[field];if(!explainerMeta(o)||o.explainerAsset.style!=='vector'||!def||o.locked)throw Error('Select an unlocked vector object and an available part.');if(!Number.isFinite(value)||!Number.isFinite(t)||t<0||t>current().duration)throw Error('Keep part keys inside the scene.');const track=(o.objectAnimation??={})[field]??=[];if(!track.length&&t>.015)track.push({t:0,value:partDefault(o,field,0),ease});const at=Math.round(t*1000)/1000,key=track.find(k=>Math.abs(k.t-at)<.015);if(key){key.value=clamp(value,def[1],def[2]);key.ease=ease}else track.push({t:at,value:clamp(value,def[1],def[2]),ease});track.sort((a,b)=>a.t-b.t)}
const propBeforePartKeys=prop;prop=function(c,o,v){if(o.type==='image'&&o.explainerAsset?.style==='vector'){const p=objectPartPose(o,time);return propBeforePartKeys(c,{...o,explainerAsset:{...o.explainerAsset,partPose:p}},{...v,rotation:v.rotation+(p.artworkAngle??0),scale:v.scale*(p.artworkScale??1)})}return propBeforePartKeys(c,o,v)};
let partEditorObjectId=null,partEditorSceneId=null,partEditorField='artworkAngle',partEditorDirty=false;
document.body.insertAdjacentHTML('beforeend',`<dialog id="objectPartsDialog"><div class="tool-heading"><div><div class="eyebrow">MAKE EVERY DETAIL MOVE</div><h2>Object parts</h2></div><button id="closeObjectParts">Done</button></div><div class="production-two-col"><div><canvas id="objectPartsPreview" width="640" height="360"></canvas><label>Time<input id="objectPartsTime" type="range" min="0" max="6" step="0.01"></label><div id="objectPartKeyList" class="body-animation-keys"></div><button id="playObjectParts">Play from here</button></div><div><label>Part<select id="objectPartField"></select></label><label><span id="objectPartValueLabel">Value</span><input id="objectPartValue" type="range"><output id="objectPartValueText"></output></label><label>Between keys<select id="objectPartEase"><option value="smooth">Smooth</option><option value="linear">Even speed</option><option value="hold">Hold</option></select></label><button id="addObjectPartKey" class="primary">Key this part</button><button id="deleteObjectPartKey">Delete key here</button><button id="resetObjectPart">Reset this part</button><p class="note">Part keys are independent of the object's position and rotation keys. Unkeyed details can keep their automatic animation. Pop-in, float and pulse remain in the normal inspector.</p></div></div></dialog>`);
function partEditorObject(){return current().id===partEditorSceneId?current().objects.find(o=>o.id===partEditorObjectId):null}
function commitPartEditor(){if(partEditorDirty){partEditorDirty=false;save();renderTimeline()}}
function paintObjectParts(){renderSceneFrame($('objectPartsPreview').getContext('2d'),current(),time);$('objectPartsTime').value=time;draw()}
function renderObjectPartControls(){const o=partEditorObject();if(!o)return;const defs=partDefinitions(o),select=$('objectPartField');select.replaceChildren();for(const[field,[label]]of Object.entries(defs)){const option=document.createElement('option');option.value=field;option.textContent=label;select.append(option)}if(!defs[partEditorField])partEditorField=Object.keys(defs)[0];select.value=partEditorField;const[name,min,max,step]=defs[partEditorField];$('objectPartValueLabel').textContent=name;const input=$('objectPartValue');input.min=min;input.max=max;input.step=step;input.value=clamp(objectPartValue(o,partEditorField,time),min,max);$('objectPartValueText').textContent=(+input.value).toFixed(step<1?2:0);const key=o.objectAnimation?.[partEditorField]?.find(k=>Math.abs(k.t-time)<.015);$('objectPartEase').value=key?.ease||'smooth';const list=$('objectPartKeyList');list.replaceChildren();for(const k of o.objectAnimation?.[partEditorField]||[])list.append(storyButton(k.t.toFixed(2)+'s',()=>{commitPartEditor();time=k.t;renderObjectPartControls()}));if(!list.children.length)list.textContent='No custom keys for this part.';paintObjectParts()}
async function openObjectParts(o=object()){if(!explainerMeta(o)||o.explainerAsset.style!=='vector'||o.locked)return toast('Select an unlocked 2D illustration first.');stop();partEditorObjectId=o.id;partEditorSceneId=current().id;partEditorDirty=false;$('objectPartsTime').max=current().duration;renderObjectPartControls();$('objectPartsDialog').showModal();const s=current();await preloadProductionAssets(s);if(current()===s&&$('objectPartsDialog').open)paintObjectParts()}
$('closeObjectParts').onclick=()=>$('objectPartsDialog').close();$('objectPartsDialog').addEventListener('close',()=>{commitPartEditor();render()});$('objectPartsTime').oninput=e=>{commitPartEditor();time=+e.target.value;renderObjectPartControls()};$('objectPartField').onchange=e=>{commitPartEditor();partEditorField=e.target.value;renderObjectPartControls()};$('objectPartValue').oninput=e=>{const o=partEditorObject();if(!o||o.locked)return;keyObjectPart(o,partEditorField,+e.target.value,time,$('objectPartEase').value);partEditorDirty=true;$('objectPartValueText').textContent=e.target.value;paintObjectParts()};$('objectPartValue').onchange=()=>{commitPartEditor();renderObjectPartControls()};$('objectPartEase').onchange=e=>{const o=partEditorObject(),key=o?.objectAnimation?.[partEditorField]?.find(k=>Math.abs(k.t-time)<.015);if(key&&!o.locked){key.ease=e.target.value;save();paintObjectParts()}};$('addObjectPartKey').onclick=()=>{const o=partEditorObject();if(!o)return;keyObjectPart(o,partEditorField,objectPartValue(o,partEditorField,time),time,$('objectPartEase').value);partEditorDirty=true;commitPartEditor();renderObjectPartControls()};$('deleteObjectPartKey').onclick=()=>{const o=partEditorObject();if(o?.locked||!o?.objectAnimation?.[partEditorField])return;o.objectAnimation[partEditorField]=o.objectAnimation[partEditorField].filter(k=>Math.abs(k.t-time)>.015);save();renderObjectPartControls()};$('resetObjectPart').onclick=()=>{const o=partEditorObject();if(!o||o.locked)return;if(o.objectAnimation)delete o.objectAnimation[partEditorField];save();renderObjectPartControls()};$('playObjectParts').onclick=()=>{$('objectPartsDialog').close();previewStoryRange(time,current().duration,null)};
const controlsBeforeObjectParts=renderControls;renderControls=function(){controlsBeforeObjectParts();const o=object();if(!explainerMeta(o)||o.explainerAsset.style!=='vector')return;const b=storyButton('Animate individual parts',()=>openObjectParts(o));b.id='openObjectParts';b.disabled=!!o.locked;$('explainerObjectStyle')?.closest('details')?.append(b)};
const timelineBeforeObjectParts=renderTimeline;renderTimeline=function(){timelineBeforeObjectParts();if(timelineDrag)return;for(const o of current().objects){const entries=Object.entries(o.objectAnimation||{}).filter(([_,keys])=>keys.length);if(!entries.length)continue;const row=lane('Parts · '+o.name,'object-part-track');for(const[field,keys]of entries)for(const k of keys){const b=document.createElement('button');b.className='body-timeline-key';b.style.left=(sceneOffset()+k.t)*timelineZoom+'px';b.textContent='◆';b.title=(partDefinitions(o)[field]?.[0]||field)+' · '+k.t.toFixed(2)+'s';b.disabled=!!o.locked;b.onclick=()=>{stop();selected=o.id;time=k.t;render()};b.onkeydown=e=>{if(o.locked||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();k.t=clamp(k.t+(e.key==='ArrowRight'?1:-1)/30,0,current().duration);keys.sort((a,b)=>a.t-b.t);time=k.t;save();render()};row.area.append(b)}}};
const moveBeforeObjectParts=moveVisual;moveVisual=function(o,change){const start=clipStart(o);moveBeforeObjectParts(o,change);const delta=clipStart(o)-start;if(change.mode==='move'&&delta)for(const keys of Object.values(o.objectAnimation||{}))for(const k of keys)k.t=clamp(k.t+delta,0,current().duration)};
const durationBeforeObjectParts=changeSceneDuration;changeSceneDuration=function(s,n){if(s.objects.some(o=>Object.values(o.objectAnimation||{}).some(keys=>keys.some(k=>k.t>+n+.001))))return toast('Move object-part keys before shortening this scene.'),false;return durationBeforeObjectParts(s,n)};
const validBeforeObjectParts=valid;valid=function(p){try{return validBeforeObjectParts(p)&&p.scenes.every(s=>s.objects.every(o=>!o.objectAnimation||!!explainerMeta(o)&&Object.entries(o.objectAnimation).every(([field,keys])=>Object.hasOwn(partDefinitions(o),field)&&Array.isArray(keys)&&keys.length<=500&&keys.every(k=>k&&Number.isFinite(k.t)&&k.t>=0&&k.t<=s.duration+.001&&Number.isFinite(k.value)&&k.value>=partDefinitions(o)[field][1]&&k.value<=partDefinitions(o)[field][2]&&['smooth','linear','hold','ease-in','ease-out','bounce','cubic'].includes(k.ease)&&(!k.curve||Array.isArray(k.curve)&&k.curve.length===4&&k.curve.every(Number.isFinite)&&k.curve[0]>=0&&k.curve[0]<=1&&k.curve[2]>=0&&k.curve[2]<=1&&k.curve[1]>=-2&&k.curve[1]<=3&&k.curve[3]>=-2&&k.curve[3]<=3)))))}catch{return false}};
